/**
 * Homebrew data fetching utilities.
 *
 * Provides functions for fetching installed and outdated packages.
 *
 * Installed packages come from `brew info --json=v2 --installed`, served from a
 * cache invalidated by watching brew's own state (see `readCache`).
 */

import * as fs from "fs/promises";
import path from "path";
import {
  Cask,
  Formula,
  InstallableResults,
  InstalledMap,
  OutdatedResults,
  DownloadProgressCallback,
  ChunkedRemote,
  ChunkedCacheConfig,
  CacheIndex,
  IndexEntry,
} from "../types";
import {
  cachePath,
  downloadRemoteToCache,
  getChunkedCacheConfig,
  isChunkedCacheValid,
  buildChunkedCache,
  loadIndex,
  loadItemsFromChunks,
  IndexExtractor,
  CHUNKED_CACHE_VERSION,
} from "../cache";
import { brewPath, brewCachePrefix } from "./paths";
import { isCask, normalizeOutdatedResults } from "./helpers";
import { execBrew, execBrewJson } from "./commands";
import { parseBrewVulns, VulnResults } from "./vulns";
import { invalidateBrewMajorVersion } from "./brew-version";
import { compactCaskArtifacts } from "./link";
import { ADOPT_INDEX_FILE, adoptIndexEntry, type AdoptIndex } from "./adopt";
import { AdoptIndexUnavailableError } from "../errors";
import { brewLogger, cacheLogger } from "../logger";

/// Cache Paths

const installedCachePath = cachePath("installedv2.json");
const formulaCachePath = cachePath("formula.json");
const caskCachePath = cachePath("cask.json");

/// Remote URLs

const formulaURL = "https://formulae.brew.sh/api/formula.json";
const caskURL = "https://formulae.brew.sh/api/cask.json";

const formulaRemote: ChunkedRemote<Formula> = {
  url: formulaURL,
  cachePath: formulaCachePath,
  chunkedConfig: getChunkedCacheConfig("formula"),
};

const caskRemote: ChunkedRemote<Cask> = {
  url: caskURL,
  cachePath: caskCachePath,
  chunkedConfig: getChunkedCacheConfig("cask"),
  buildHooks: () => {
    // Accumulated per build, never shared: a module-level map would keep a
    // previous catalog's tokens after one is removed upstream.
    const adopt: AdoptIndex = {};
    return {
      // Runs on the whole record, before `compact` deletes `artifacts`.
      onRecord: (cask) => {
        const entry = adoptIndexEntry(cask);
        if (entry) adopt[cask.token] = entry;
      },
      compact: compactCaskArtifacts,
      writeSidecar: (partialDir) => fs.writeFile(path.join(partialDir, ADOPT_INDEX_FILE), JSON.stringify(adopt)),
    };
  },
};

/** Extract index entry from a Formula */
const extractFormulaIndex: IndexExtractor<Formula> = (item, chunkNumber, indexInChunk): IndexEntry => {
  return {
    id: item.name,
    n: item.name.toLowerCase(),
    d: item.desc?.toLowerCase().slice(0, 100),
    a: item.aliases?.length > 0 ? item.aliases.map((a) => a.toLowerCase()) : undefined,
    c: chunkNumber,
    i: indexInChunk,
  };
};

/** Extract index entry from a Cask */
const extractCaskIndex: IndexExtractor<Cask> = (item, chunkNumber, indexInChunk): IndexEntry => {
  return {
    id: item.token,
    n: item.token.toLowerCase(),
    d: item.desc?.toLowerCase().slice(0, 100),
    a: item.name?.length > 0 ? item.name.map((n) => n.toLowerCase()) : undefined,
    c: chunkNumber,
    i: indexInChunk,
  };
};

/**
 * Check if the search cache files exist (formula.json and cask.json).
 * Used to determine if this is a cold start (no cache) or warm start (cache exists).
 */
export async function hasSearchCache(): Promise<boolean> {
  try {
    const [formulaStats, caskStats] = await Promise.all([fs.stat(formulaCachePath), fs.stat(caskCachePath)]);
    // Both files must exist and have content
    return formulaStats.size > 0 && caskStats.size > 0;
  } catch {
    return false;
  }
}

/**
 * Fetch all installed packages with full metadata.
 */
export async function brewFetchInstalled(useCache: boolean, cancel?: AbortSignal): Promise<InstalledMap | undefined> {
  const startTime = Date.now();
  const results = await brewFetchInstallableResults(useCache, cancel);
  const mapped = brewMapInstalled(results);
  const duration = Date.now() - startTime;

  if (mapped) {
    brewLogger.log("Installed packages fetched", {
      formulaeCount: mapped.formulae.size,
      casksCount: mapped.casks.size,
      totalCount: mapped.formulae.size + mapped.casks.size,
      durationMs: duration,
      fromCache: useCache,
    });
  }

  return mapped;
}

/**
 * Fetch all installed packages with full metadata, in their serializable form.
 *
 * Prefer this over {@link brewFetchInstalled} when the result is persisted:
 * `InstalledMap` holds `Map`s, and `JSON.stringify(new Map())` is `{}`, so a
 * mapped value does not survive a cache round-trip. Rebuild the lookup
 * structures on read with {@link brewMapInstalled}.
 */
export async function brewFetchInstallableResults(
  useCache: boolean,
  cancel?: AbortSignal,
): Promise<InstallableResults | undefined> {
  async function installed(): Promise<string> {
    return (await execBrew(`info --json=v2 --installed`, { signal: cancel })).stdout;
  }

  if (!useCache) {
    return JSON.parse(await installed());
  }

  async function updateCache(): Promise<InstallableResults> {
    const startTime = Date.now();
    const info = await installed();
    const parsed = JSON.parse(info) as InstallableResults;
    const duration = Date.now() - startTime;

    try {
      await fs.writeFile(installedCachePath, info);
      const responseSizeBytes = Buffer.byteLength(info, "utf8");
      const responseSizeKb = (responseSizeBytes / 1024).toFixed(2);

      cacheLogger.log("Updated installed cache", {
        path: installedCachePath,
        formulaeCount: parsed.formulae.length,
        casksCount: parsed.casks.length,
        totalCount: parsed.formulae.length + parsed.casks.length,
        durationMs: duration,
        responseSizeBytes,
        responseSizeKb: `${responseSizeKb} KB`,
      });
    } catch (err) {
      cacheLogger.error("Failed to write installed cache", {
        path: installedCachePath,
        formulaeCount: parsed.formulae.length,
        casksCount: parsed.casks.length,
        error: err,
      });
    }
    return parsed;
  }

  async function mtimeMs(path: string): Promise<number> {
    return (await fs.stat(path)).mtimeMs;
  }

  /** 0 when the path does not exist, so a missing marker never blocks a refresh. */
  async function mtimeMsOrZero(path: string): Promise<number> {
    try {
      return await mtimeMs(path);
    } catch {
      return 0;
    }
  }

  async function readCache(): Promise<InstallableResults> {
    const cacheTime = await mtimeMs(installedCachePath);
    // 'var/homebrew/locks' is updated after installed keg_only or linked formula.
    const locksTime = await mtimeMs(brewPath("var/homebrew/locks"));
    // Casks
    const caskroomTime = await mtimeMs(brewPath("Caskroom"));

    // 'var/homebrew/pinned' is updated after pin/unpin actions (but does not exist if there are no pinned formula).
    const pinnedTime = await mtimeMsOrZero(brewPath("var/homebrew/pinned"));
    // Cask pins live in a SEPARATE directory (startup/config.rb: HOMEBREW_PINNED_CASKS),
    // which unpin removes when it empties. The parent check below only catches the
    // first cask pin — creating the directory bumps var/homebrew — so probe it too.
    const pinnedCasksTime = await mtimeMsOrZero(brewPath("var/homebrew/pinned_casks"));
    // Because '/var/homebrew/pinned can be removed, we need to also check the parent directory'
    const homebrewTime = await mtimeMs(brewPath("var/homebrew"));

    // Everything above tracks LOCAL state — what is installed, linked, pinned.
    // None of it moves when `brew update` learns that an installed package has
    // a newer version, so without the two below the cached `outdated` flags
    // stay false forever and Search reports an outdated package as current.
    // Since Homebrew 4 the index is the JSON API cache; the repo's FETCH_HEAD
    // covers a git-based install. Either may be absent, hence OrZero.
    const apiIndexTime = await mtimeMsOrZero(path.join(brewCachePrefix, "api"));
    const fetchHeadTime = await mtimeMsOrZero(brewPath(".git/FETCH_HEAD"));

    if (
      homebrewTime < cacheTime &&
      caskroomTime < cacheTime &&
      locksTime < cacheTime &&
      pinnedTime < cacheTime &&
      pinnedCasksTime < cacheTime &&
      apiIndexTime < cacheTime &&
      fetchHeadTime < cacheTime
    ) {
      const cacheBuffer = await fs.readFile(installedCachePath);
      const cached = JSON.parse(cacheBuffer.toString()) as InstallableResults;
      cacheLogger.log("Using cached installed data", {
        path: installedCachePath,
        formulaeCount: cached.formulae.length,
        casksCount: cached.casks.length,
        totalCount: cached.formulae.length + cached.casks.length,
        cacheAgeMs: Date.now() - cacheTime,
      });
      return cached;
    } else {
      cacheLogger.log("Cache invalidated, refreshing", {
        reason: "brew state changed",
        homebrewTime,
        caskroomTime,
        locksTime,
        pinnedTime,
        pinnedCasksTime,
        cacheTime,
      });
      return await updateCache();
    }
  }

  try {
    return await readCache();
  } catch {
    return await updateCache();
  }
}

/**
 * Narrow an untrusted value to {@link InstallableResults}.
 *
 * Values read back out of a cache are not guaranteed to be what was written:
 * an entry persisted by an earlier version of the extension holds the mapped
 * form, whose `Map`s serialized to `{}`. Such an entry must be rejected rather
 * than rendered as an empty package list.
 */
export function asInstallableResults(value: unknown): InstallableResults | undefined {
  if (!value || typeof value !== "object") {
    return undefined;
  }

  const { formulae, casks } = value as Partial<InstallableResults>;
  if (!Array.isArray(formulae) || !Array.isArray(casks)) {
    return undefined;
  }

  return { formulae, casks };
}

export function brewMapInstalled(installed?: InstallableResults): InstalledMap | undefined {
  if (!installed) {
    return undefined;
  }

  const formulae = new Map<string, Formula>();
  for (const formula of installed.formulae) {
    formulae.set(formula.name, formula);
  }

  const casks = new Map<string, Cask>();
  for (const cask of installed.casks) {
    casks.set(cask.token, cask);
  }

  return { formulae: formulae, casks: casks };
}

/**
 * Fetch outdated packages.
 *
 * @param greedy - Include auto-updating casks
 * @param cancel - AbortController for cancellation
 * @param skipUpdate - Skip brew update (use cached index). Faster but may miss recent updates.
 */
export async function brewFetchOutdated(
  greedy: boolean,
  cancel?: AbortSignal,
  skipUpdate = false,
): Promise<OutdatedResults> {
  brewLogger.log("Fetching outdated packages", { greedy, skipUpdate });
  let cmd = `outdated --json=v2`;
  if (greedy) {
    cmd += " --greedy"; // include auto_update casks
  }
  // 'outdated' is only reliable after performing a 'brew update'
  // skipUpdate allows showing stale data quickly, then refreshing
  if (!skipUpdate) {
    await brewUpdate(cancel);
  }
  const output = await execBrew(cmd, { signal: cancel });
  const results = normalizeOutdatedResults(JSON.parse(output.stdout) as OutdatedResults);
  brewLogger.log("Outdated packages fetched", {
    formulaeCount: results.formulae.length,
    casksCount: results.casks.length,
    skipUpdate,
  });
  return results;
}

/**
 * Scan installed formulae for known OSV advisories (`brew vulns`, Homebrew 7).
 *
 * `brew vulns` exits 1 whenever it found an open advisory — the normal case —
 * and it prints the JSON before setting that status, so a non-zero exit with
 * JSON on stdout is a success. Only an exit with nothing on stdout (an unknown
 * formula, a broken brew) is a real failure, and then brew's own `ExecError`
 * is rethrown so its stderr reaches the failure toast. Warnings brew emits
 * alongside a good scan (untrusted tap, missing SBOM) are logged, not surfaced.
 */
export async function brewFetchVulns(cancel?: AbortSignal): Promise<VulnResults> {
  brewLogger.log("Scanning for vulnerabilities");

  const parse = (stdout: string, stderr: string | undefined): VulnResults => {
    if (stderr?.trim()) {
      brewLogger.warn("brew vulns reported warnings", { stderr: stderr.trim() });
    }
    const results = parseBrewVulns(stdout);
    brewLogger.log("Vulnerability scan complete", {
      findingsCount: results.findings.length,
      skippedCount: results.skipped.length,
    });
    return results;
  };

  const output = await execBrewJson("vulns --json", { signal: cancel });
  try {
    return parse(output.stdout, output.stderr);
  } catch (err) {
    throw output.exitError ?? err; // brew's stderr says more than our ParseError would
  }
}

/**
 * Run brew update.
 */
export async function brewUpdate(cancel?: AbortSignal): Promise<void> {
  brewLogger.log("Running brew update");
  await execBrew(`update`, { signal: cancel });
  // `brew update` can upgrade Homebrew itself, so the memoised major version is
  // now a guess. Dropping it here covers every caller (background refresh,
  // Check for Updates, the outdated fetch); the next mount re-reads.
  invalidateBrewMajorVersion();
  brewLogger.log("Brew update completed");
}

/**
 * Re-check ONE package for a newer version.
 *
 * Homebrew computes `outdated` against the tap checkouts on disk, so a package
 * installed at the newest version brew currently KNOWS about reads as up to
 * date however stale that checkout is — which is why a formula with a release
 * waiting shows no update badge until something runs `brew update`.
 *
 * The refresh is unavoidably global: Homebrew has no per-tap, let alone
 * per-formula, update. What is scoped is the re-read afterwards — one
 * `brew info` for the package the user asked about, rather than the full
 * `brew outdated` sweep the Check for Updates command runs.
 *
 * Returns the package's fresh record, or undefined if it could not be read.
 *
 * `undefined` is deliberately NOT reported as "brew no longer has this
 * package". The single-package fetchers swallow every error, so undefined
 * covers a genuine not-found AND a `brew info` that failed or returned
 * unparseable JSON — a caller that names deletion would be guessing.
 *
 * Cancellation IS separated out and re-thrown, because that one is knowable:
 * without it, a user who canceled mid-`brew info` got the same undefined and
 * an error toast for an operation they themselves stopped.
 */
export async function brewCheckForUpdate(
  item: Cask | Formula,
  cancel?: AbortSignal,
): Promise<Cask | Formula | undefined> {
  await brewUpdate(cancel);
  const fresh = isCask(item)
    ? await brewFetchCaskInfo(item.token, cancel)
    : await brewFetchFormulaInfo(item.name, cancel);
  if (fresh === undefined && cancel?.aborted) {
    const error = new Error("Aborted");
    error.name = "AbortError";
    throw error;
  }
  return fresh;
}

/// Chunked Cache Functions

/**
 * Mutable per-type state for index fetching.
 *
 * Holds the remote descriptor plus two guards:
 * - `buildInProgress`: mutex so a cold-start build and a background refresh of
 *   the same type never run concurrently.
 * - `backgroundRefresh`: dedup so we only schedule one background refresh at a
 *   time after serving a stale index.
 */
interface IndexFetchState<T> {
  remote: ChunkedRemote<T>;
  extractIndex: IndexExtractor<T>;
  buildInProgress: Promise<void> | null;
  backgroundRefresh: Promise<void> | null;
}

const formulaIndexState: IndexFetchState<Formula> = {
  remote: formulaRemote,
  extractIndex: extractFormulaIndex,
  buildInProgress: null,
  backgroundRefresh: null,
};

const caskIndexState: IndexFetchState<Cask> = {
  remote: caskRemote,
  extractIndex: extractCaskIndex,
  buildInProgress: null,
  backgroundRefresh: null,
};

/**
 * Listeners notified when a background index refresh swaps in fresh data.
 * The search hook subscribes to revalidate so the UI reflects the new index
 * (the initial search runs against the stale on-disk index for instant results).
 */
const indexRefreshListeners = new Set<() => void>();

/**
 * Subscribe to background index refresh completions (fresh data available).
 * Returns an unsubscribe function.
 */
export function onIndexRefreshed(listener: () => void): () => void {
  indexRefreshListeners.add(listener);
  return () => {
    indexRefreshListeners.delete(listener);
  };
}

function notifyIndexRefreshed(): void {
  for (const listener of indexRefreshListeners) {
    try {
      listener();
    } catch (err) {
      brewLogger.warn("Index refresh listener failed", {
        error: err instanceof Error ? err.message : String(err),
      });
    }
  }
}

/**
 * Drop the in-memory chunked index for both formulae and casks.
 * Use after deleting on-disk cache so the next search rebuilds from scratch
 * instead of reusing index entries that point to deleted chunk files.
 */
export function invalidateChunkedCacheMemory(): void {
  formulaRemote.index = undefined;
  formulaRemote.indexFetch = undefined;
  caskRemote.index = undefined;
  caskRemote.indexFetch = undefined;
}

/**
 * Force the cask chunked cache to be rebuilt, sidecar included.
 *
 * The recovery path for a missing or damaged `adopt-index.json`. A plain
 * revalidate cannot fix it: the chunk cache is still valid and current by its
 * own test, so nothing would rebuild, and the sidecar would stay missing until
 * the catalog next changed upstream.
 *
 * It deliberately deletes NOTHING. The build writes into `cask.partial` and only
 * swaps on success, so leaving the live directory in place keeps it as the
 * stale fallback if this rebuild fails — offline, say. Removing it first
 * would mean a failed recovery for an Adopt-only file left Search with no
 * casks at all.
 *
 * It also goes through `buildInProgress`, the same mutex every other cask
 * build takes, so it cannot race a background refresh over the shared
 * `cask.partial` directory. If a build is already running, that build writes
 * the sidecar too, so waiting for it is the whole job.
 */
export async function rebuildCaskIndex(onProgress?: DownloadProgressCallback, signal?: AbortSignal): Promise<void> {
  const state = caskIndexState;
  if (state.buildInProgress) {
    await state.buildInProgress;
    return;
  }
  state.buildInProgress = ensureChunkedCache(state.remote, state.extractIndex, onProgress, signal, { force: true });
  try {
    await state.buildInProgress;
  } finally {
    state.buildInProgress = null;
  }
  // Only after success: Search re-reads the fresh index on its next query.
  state.remote.index = undefined;
  state.remote.indexFetch = undefined;
}

/**
 * Full cask records for a handful of tokens, out of the chunked cache.
 *
 * Only ever called with the tokens that already matched an installed app's
 * bundle name — 16 or so — so this loads a couple of chunk files, not the
 * catalog. A token with no entry is simply absent from the result: the caller
 * treats that as "the index and the chunks are out of step" and skips it.
 */
export async function loadCasksByToken(tokens: readonly string[]): Promise<Cask[]> {
  if (tokens.length === 0) return [];
  const wanted = new Set(tokens);
  const index = await loadIndex(caskRemote.chunkedConfig);
  const entries = index.entries.filter((entry) => wanted.has(entry.id));
  return loadItemsFromChunks<Cask>(caskRemote.chunkedConfig, entries);
}

/**
 * The derived index the Adopt scan matches against, or a reason it cannot.
 *
 * Every failure here reads the same way to a user — an empty list — and an
 * empty list is a *claim*: "nothing on this Mac is adoptable". That claim is
 * false whenever the file is merely missing or damaged, so this never returns
 * an empty index. It throws, and the command renders "the cask index needs
 * rebuilding" with a Rebuild action.
 *
 * A damaged file is deleted on the way out so the next build replaces it,
 * rather than failing identically forever.
 */
export async function loadAdoptIndex(): Promise<AdoptIndex> {
  const indexPath = path.join(caskRemote.chunkedConfig.baseDir, ADOPT_INDEX_FILE);
  let raw: string;
  try {
    raw = await fs.readFile(indexPath, "utf-8");
  } catch {
    throw new AdoptIndexUnavailableError("The cask index has not been built yet.");
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    await fs.unlink(indexPath).catch(() => {});
    throw new AdoptIndexUnavailableError("The cask index is damaged.");
  }

  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    await fs.unlink(indexPath).catch(() => {});
    throw new AdoptIndexUnavailableError("The cask index is damaged.");
  }

  const index = parsed as AdoptIndex;
  // No catalog has zero app-bearing casks — there are ~4,100 — so an empty
  // object is damage rather than a result, and must not read as one.
  if (Object.keys(index).length === 0) {
    await fs.unlink(indexPath).catch(() => {});
    throw new AdoptIndexUnavailableError("The cask index is empty.");
  }
  return index;
}

/**
 * Load an existing on-disk chunked index if one is present and usable.
 * Returns undefined on a cold start (no cache) or if the on-disk schema version
 * doesn't match — in which case the chunk files may not line up with these
 * index entries, so the caller must rebuild rather than serve them.
 */
async function tryLoadOnDiskIndex(config: ChunkedCacheConfig): Promise<CacheIndex | undefined> {
  try {
    const index = await loadIndex(config);
    if (index.meta.version !== CHUNKED_CACHE_VERSION) {
      return undefined;
    }
    return index;
  } catch {
    // No usable on-disk index (cold start, or a partially-cleared cache).
    return undefined;
  }
}

/**
 * Refresh a served stale index in the background.
 *
 * Deliberately signal-less: like the initial index download, the refresh must
 * outlive the per-keystroke search aborts. `ensureChunkedCache` is a no-op when
 * the on-disk cache is already fresh, so this is cheap when nothing changed.
 * Only notifies listeners when the rebuild actually swapped in newer data.
 */
function scheduleBackgroundRefresh<T>(state: IndexFetchState<T>): void {
  if (state.backgroundRefresh) {
    return;
  }

  const { remote, extractIndex } = state;
  const previousLastModified = remote.index?.meta.lastModified;

  state.backgroundRefresh = (async () => {
    try {
      if (state.buildInProgress) {
        await state.buildInProgress;
      } else {
        state.buildInProgress = ensureChunkedCache(remote, extractIndex);
        try {
          await state.buildInProgress;
        } finally {
          state.buildInProgress = null;
        }
      }

      const index = await loadIndex(remote.chunkedConfig);
      remote.index = index;

      if (index.meta.lastModified !== previousLastModified) {
        brewLogger.log("Background index refresh updated cache", { type: remote.chunkedConfig.type });
        notifyIndexRefreshed();
      }
    } catch (err) {
      // Non-fatal: we already served the stale index. Log and move on.
      brewLogger.warn("Background index refresh failed", {
        type: remote.chunkedConfig.type,
        error: err instanceof Error ? err.message : String(err),
      });
    } finally {
      state.backgroundRefresh = null;
    }
  })();
}

/**
 * Fetch the chunked index for a given type.
 *
 * Resolution order:
 * 1. In-memory index (fastest, warm hook).
 * 2. An in-flight fetch (deduplication).
 * 3. An existing on-disk index — served immediately so incremental search
 *    works right away, with a background refresh kicked off to pick up any
 *    remote changes.
 * 4. Cold start (no on-disk index) — build before returning; search can't
 *    proceed without any index at all.
 */
async function fetchIndex<T>(
  state: IndexFetchState<T>,
  onProgress?: DownloadProgressCallback,
  signal?: AbortSignal,
): Promise<CacheIndex> {
  const { remote, extractIndex } = state;

  // 1. Already cached in memory
  if (remote.index) {
    return remote.index;
  }

  // 2. Fetch already in progress (deduplication)
  if (remote.indexFetch) {
    // Don't pass our signal to the existing build - just await it
    try {
      const result = await remote.indexFetch;
      // Check abort after awaiting another caller's build
      if (signal?.aborted) {
        const error = new Error("Aborted");
        error.name = "AbortError";
        throw error;
      }
      return result;
    } catch (err) {
      // If the existing build was aborted but OUR signal is still active, retry
      if (err instanceof Error && err.name === "AbortError" && !signal?.aborted) {
        return fetchIndex(state, onProgress, signal);
      }
      throw err;
    }
  }

  // 3. Serve an existing on-disk index immediately, refresh in the background.
  // This is the warm-but-stale start: rather than blocking the first search on
  // a multi-second re-download, search the index we already have and swap in
  // fresh data when the background refresh finishes.
  const staleIndex = await tryLoadOnDiskIndex(remote.chunkedConfig);
  if (staleIndex) {
    remote.index = staleIndex;
    brewLogger.log("Serving on-disk index, refreshing in background", { type: remote.chunkedConfig.type });
    scheduleBackgroundRefresh(state);
    return staleIndex;
  }

  // 4. Cold start: no usable on-disk index, so we must build before searching.
  remote.indexFetch = (async () => {
    // Use mutex to prevent concurrent builds
    if (state.buildInProgress) {
      brewLogger.log("Waiting for existing chunked cache build", { type: remote.chunkedConfig.type });
      await state.buildInProgress;
    } else {
      state.buildInProgress = ensureChunkedCache(remote, extractIndex, onProgress, signal);
      try {
        await state.buildInProgress;
      } finally {
        state.buildInProgress = null;
      }
    }

    // Load index
    const index = await loadIndex(remote.chunkedConfig);
    remote.index = index;
    return index;
  })();

  try {
    return await remote.indexFetch;
  } finally {
    remote.indexFetch = undefined;
  }
}

/**
 * Ensure chunked cache exists and is valid.
 * Downloads source JSON to disk (without parsing) and builds chunks.
 */
async function ensureChunkedCache<T>(
  remote: ChunkedRemote<T>,
  extractIndex: IndexExtractor<T>,
  onProgress?: DownloadProgressCallback,
  signal?: AbortSignal,
  /** Rebuild even when the cache is current — the sidecar recovery path. */
  options: { force?: boolean } = {},
): Promise<void> {
  if (!options.force && (await isChunkedCacheValid(remote.chunkedConfig, remote.url, signal))) {
    return;
  }

  // Check if a stale but USABLE cache exists (for fallback on failure). The
  // files merely existing is not enough: after a schema-version bump the
  // on-disk chunks are the previous shape, so falling back to them serves
  // records missing whatever the bump added. Same acceptance as the warm-start
  // path, so a fallback can only ever serve what `fetchIndex` would serve.
  const hasStaleCacheIndex = (await tryLoadOnDiskIndex(remote.chunkedConfig)) !== undefined;

  try {
    brewLogger.log("Building chunked cache", { type: remote.chunkedConfig.type });

    // Download to disk only (no parsing). Critical to avoid heap exhaustion.
    await downloadRemoteToCache(remote.url, remote.cachePath, onProgress, signal);

    // Stream the downloaded file into chunks + index + meta.
    await buildChunkedCache(
      remote.cachePath,
      remote.url,
      remote.chunkedConfig,
      extractIndex,
      onProgress,
      signal,
      remote.buildHooks?.(),
    );
    return;
  } catch (err) {
    if (err instanceof Error && err.name === "AbortError") throw err;

    // If the build failed because the source JSON couldn't be parsed, the
    // file on disk is corrupt (truncated by a killed process, or a chunked
    // transfer that ended early without Content-Length). Delete it so the
    // *next* attempt — whether via the toast action, reopening the command,
    // or another search — downloads fresh rather than parsing the same bad
    // bytes. We don't retry inline because doubling the wait on a flaky
    // connection makes the failure look like a hang.
    if (err instanceof Error && err.name === "ParseError") {
      try {
        await fs.unlink(remote.cachePath);
        brewLogger.warn("Discarded corrupt source cache", {
          type: remote.chunkedConfig.type,
          path: remote.cachePath,
          error: err.message,
        });
      } catch {
        // Ignore — file may already be gone
      }
    }

    // Fall back to stale cache if we still have a usable one.
    if (hasStaleCacheIndex) {
      brewLogger.warn("Chunked cache rebuild failed, using stale cache", {
        type: remote.chunkedConfig.type,
        error: err instanceof Error ? err.message : String(err),
      });
      return;
    }

    throw err;
  }
}

/**
 * The on-disk index for a type, if one is already there and usable — never a
 * build, never a background refresh.
 *
 * For lookups that are only worth doing against a cache that already exists.
 * `fetchIndex` cannot serve them: on a cold or schema-stale cache it downloads
 * and rebuilds the whole chunked cache, and on a warm one it schedules a
 * background rebuild — both of which spike memory for a caller that wanted one
 * chunk read. This returns `undefined` in exactly those cases instead.
 */
async function cachedIndex<T>(state: IndexFetchState<T>): Promise<CacheIndex | undefined> {
  return state.remote.index ?? (await tryLoadOnDiskIndex(state.remote.chunkedConfig));
}

/** The already-built formula index, or undefined. See {@link cachedIndex}. */
export function cachedFormulaIndex(): Promise<CacheIndex | undefined> {
  return cachedIndex(formulaIndexState);
}

/** The already-built cask index, or undefined. See {@link cachedIndex}. */
export function cachedCaskIndex(): Promise<CacheIndex | undefined> {
  return cachedIndex(caskIndexState);
}

/**
 * Fetch the chunked index for formulae.
 * Serves an existing on-disk index immediately (refreshing in the background),
 * or builds the chunked cache on a cold start.
 */
export async function fetchFormulaIndex(
  onProgress?: DownloadProgressCallback,
  signal?: AbortSignal,
): Promise<CacheIndex> {
  return fetchIndex(formulaIndexState, onProgress, signal);
}

/**
 * Fetch the chunked index for casks.
 * Serves an existing on-disk index immediately (refreshing in the background),
 * or builds the chunked cache on a cold start.
 */
export async function fetchCaskIndex(onProgress?: DownloadProgressCallback, signal?: AbortSignal): Promise<CacheIndex> {
  return fetchIndex(caskIndexState, onProgress, signal);
}

/**
 * Fetch specific formulae by their index entries.
 * Only loads the chunks containing the requested items.
 */
export async function fetchFormulaItems(entries: IndexEntry[]): Promise<Formula[]> {
  return loadItemsFromChunks<Formula>(formulaRemote.chunkedConfig, entries);
}

/**
 * Fetch specific casks by their index entries.
 * Only loads the chunks containing the requested items.
 */
export async function fetchCaskItems(entries: IndexEntry[]): Promise<Cask[]> {
  return loadItemsFromChunks<Cask>(caskRemote.chunkedConfig, entries);
}

/**
 * Fetch info for a single formula by name.
 * Much faster than fetching all installed packages.
 */
export async function brewFetchFormulaInfo(name: string, cancel?: AbortSignal): Promise<Formula | undefined> {
  const startTime = Date.now();
  brewLogger.log("Fetching formula info", { name });

  try {
    const output = await execBrew(`info --json=v2 ${name}`, { signal: cancel });
    const results = JSON.parse(output.stdout) as InstallableResults;
    const duration = Date.now() - startTime;

    if (results.formulae.length > 0) {
      brewLogger.log("Formula info fetched", { name, durationMs: duration });
      return results.formulae[0];
    }

    brewLogger.warn("Formula not found", { name, durationMs: duration });
    return undefined;
  } catch (err) {
    brewLogger.error("Failed to fetch formula info", { name, error: err });
    return undefined;
  }
}

/**
 * Fetch info for a single cask by token.
 * Much faster than fetching all installed packages.
 */
export async function brewFetchCaskInfo(token: string, cancel?: AbortSignal): Promise<Cask | undefined> {
  const startTime = Date.now();
  brewLogger.log("Fetching cask info", { token });

  try {
    // `--cask` is required, not decorative: without it brew's resolver prefers a
    // same-named FORMULA (cli/named_args.rb), returning an empty `casks` array.
    const output = await execBrew(`info --json=v2 --cask ${token}`, { signal: cancel });
    const results = JSON.parse(output.stdout) as InstallableResults;
    const duration = Date.now() - startTime;

    if (results.casks.length > 0) {
      brewLogger.log("Cask info fetched", { token, durationMs: duration });
      return results.casks[0];
    }

    brewLogger.warn("Cask not found", { token, durationMs: duration });
    return undefined;
  } catch (err) {
    brewLogger.error("Failed to fetch cask info", { token, error: err });
    return undefined;
  }
}
